// uuid_clear: zero out an existing uuid_t buffer.
// Requirements: uu must be non-NULL and writable 16-byte buffer. The fuzzer runtime
// guarantees non-NULL input objects; we simply invoke the API.
uuid_clear(*uu);
// Validation: No return value. We keep uu as an output so it remains in the pool.

// uuid_compare: compare two UUIDs; neither buffer is modified.
// Requirements: pointers must be non-NULL and point to valid 16-byte UUIDs.
// Invoke and ignore result here; other stubs may assert properties if needed.
int cmp = uuid_compare(*uu1, *uu2);
// Track comparison outcome for potential downstream logic.
FUZZ_SET_ATTR_INT(uu1, "last_compare_with", (int)(uintptr_t)uu2);
FUZZ_SET_ATTR_INT(uu1, "last_compare_result", cmp);
// Validation: Inputs are preserved and returned as outputs.

// uuid_copy: copy src into dst.
// Requirements: dst must be writable; src must be a valid UUID; neither is NULL.
uuid_copy(*dst, *src);
// Optionally record that dst now mirrors src.
FUZZ_SET_ATTR_PTR(dst, "copied_from", (void*)src);
// Validation: Both objects persist; we return both.

// uuid_is_null: check for nil UUID.
int is_nil = uuid_is_null(*uu);
FUZZ_SET_ATTR_INT(uu, "is_nil", is_nil);
// Validation: No modification required; uu is returned so it persists.

// uuid_unparse: write canonical lowercase-with-hyphens string, NUL-terminated.
char buf[37];
uuid_unparse(*uu, buf);
// Optionally record last formatting result for later cross-checks.
FUZZ_SET_ATTR_STR(uu, "last_unparse", buf);
// Validation: Buffer is local; uu returned to pool.

// uuid_unparse_lower: canonical lowercase formatting.
char buf[37];
uuid_unparse_lower(*uu, buf);
FUZZ_SET_ATTR_STR(uu, "last_unparse_lower", buf);
// Validation: uu preserved and returned.

// uuid_unparse_upper: canonical uppercase formatting.
char buf[37];
uuid_unparse_upper(*uu, buf);
FUZZ_SET_ATTR_STR(uu, "last_unparse_upper", buf);
// Validation: uu preserved and returned.

// uuid_time: extract generation time from a time-based UUID.
// ret_tv may be NULL; vary this to exercise both paths.
unsigned int flag = *FUZZ_PARAM(unsigned int);
if ((flag & 1u) != 0u) {
    struct timeval tv;
    (void)uuid_time(*uu, &tv);
    // Record that we captured a timeval.
    FUZZ_SET_ATTR_INT(uu, "last_time_had_tv", 1);
} else {
    (void)uuid_time(*uu, (struct timeval*)nullptr);
    FUZZ_SET_ATTR_INT(uu, "last_time_had_tv", 0);
}
// Validation: uu preserved and returned; we do not assert semantics for non-time-based UUIDs.

// uuid_type: returns version; attach for downstream assertions.
int t = uuid_type(*uu);
FUZZ_SET_ATTR_INT(uu, "version", t);
// Validation: uu unchanged and returned.

// uuid_variant: returns variant; attach for downstream assertions.
int v = uuid_variant(*uu);
FUZZ_SET_ATTR_INT(uu, "variant", v);
// Validation: uu unchanged and returned.

// uuid_generate: fill an existing writable uuid_t buffer from the pool.
// Requirement: out must be non-NULL and writable 16-byte buffer; runtime provides it.
uuid_generate(*out);
// Record provenance for downstream checks.
FUZZ_SET_ATTR_STR(out, "gen_kind", "default");
// Validation: out remains valid and is returned to the pool.

// uuid_generate_random: generate a version 4 UUID into an existing buffer.
// Requirement: out is a non-NULL writable 16-byte buffer.
uuid_generate_random(*out);
FUZZ_SET_ATTR_STR(out, "gen_kind", "random_v4");
// Validation: out persists; returned to the pool.

// uuid_generate_time: generate time-based UUID (traditionally v1) into existing buffer.
// Requirement: out is a non-NULL writable 16-byte buffer.
uuid_generate_time(*out);
FUZZ_SET_ATTR_STR(out, "gen_kind", "time_v1");
// Validation: out persists; returned to the pool.

// uuid_generate_time_safe: generate time-based UUID with safety status.
// Requirement: out is a non-NULL writable 16-byte buffer.
int status = uuid_generate_time_safe(*out);
// Record status for downstream consumers; semantics are implementation-defined.
FUZZ_SET_ATTR_INT(out, "time_safe_status", status);
FUZZ_SET_ATTR_STR(out, "gen_kind", "time_safe");
// Validation: out is initialized regardless of status and is returned to the pool.

// uuid_generate_md5: name-based UUID v3 using MD5(ns, name[0..len)).
// Requirements: out and ns non-NULL; if len>0, name must be non-NULL and at least len bytes.
std::string name_buf = FUZZ_PARAM_STR();
size_t maxlen = name_buf.size();
size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % (maxlen + 1));
const char *name_ptr = (len == 0) ? (const char*)nullptr : name_buf.data();
// Invoke API on the provided output buffer.
uuid_generate_md5(*out, *ns, name_ptr, len);
// Track derivation metadata.
FUZZ_SET_ATTR_PTR(out, "ns", (void*)ns);
FUZZ_SET_ATTR_INT(out, "name_len", (int)len);
FUZZ_SET_ATTR_STR(out, "gen_kind", "name_md5_v3");
// Validation: ns unmodified; out initialized; both returned.

// uuid_generate_sha1: name-based UUID v5 using SHA-1(ns, name[0..len)).
// Requirements: out and ns non-NULL; if len>0, name must be non-NULL and at least len bytes.
std::string name_buf = FUZZ_PARAM_STR();
size_t maxlen = name_buf.size();
size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % (maxlen + 1));
const char *name_ptr = (len == 0) ? (const char*)nullptr : name_buf.data();
// Invoke API on the provided output buffer.
uuid_generate_sha1(*out, *ns, name_ptr, len);
// Track derivation metadata.
FUZZ_SET_ATTR_PTR(out, "ns", (void*)ns);
FUZZ_SET_ATTR_INT(out, "name_len", (int)len);
FUZZ_SET_ATTR_STR(out, "gen_kind", "name_sha1_v5");
// Validation: ns preserved; out initialized; both returned.

// uuid_parse: parse text into binary uuid stored in existing buffer.
std::string text = FUZZ_PARAM_STR();
const char *in = text.c_str(); // Ensure NUL-terminated as required.
int status = uuid_parse(in, *out);
// Track parse status and source text for downstream checks.
FUZZ_SET_ATTR_INT(out, "parsed_ok", status);
FUZZ_SET_ATTR_STR(out, "source_text", in);
// Validation: out is always returned; callers can branch on parsed_ok.

// uuid_parse_range: parse from [in_start, in_end) into existing buffer.
std::string text = FUZZ_PARAM_STR();
size_t n = text.size();
// Pick a valid range with start <= end.
size_t i = (size_t)(*FUZZ_PARAM(unsigned int) % (n + 1));
size_t j = (size_t)(*FUZZ_PARAM(unsigned int) % (n + 1));
if (i > j) { size_t tmp = i; i = j; j = tmp; }
const char *in_start = text.data() + i;
const char *in_end   = text.data() + j;
int status = uuid_parse_range(in_start, in_end, *out);
// Track attributes for later validation.
FUZZ_SET_ATTR_INT(out, "parsed_ok", status);
FUZZ_SET_ATTR_INT(out, "range_start", (int)i);
FUZZ_SET_ATTR_INT(out, "range_end", (int)j);
FUZZ_SET_ATTR_STR(out, "source_text_fragment", "range");
// Validation: in_start <= in_end enforced; out returned regardless of status.

// uuid_get_template: retrieve pointer to predefined template by alias.
// We exercise both known/unknown alias paths by using fuzzed strings.
std::string alias_s = FUZZ_PARAM_STR();
const char *alias = alias_s.c_str();
const uuid_t *tpl = uuid_get_template(alias);
// If non-NULL, the returned memory is read-only; do not modify or free.
// Record global metadata for potential cross-stub diagnostics.
if (tpl) {
    FUZZ_SET_ATTR_STR_GLOBAL("last_template_alias", alias);
} else {
    FUZZ_SET_ATTR_STR_GLOBAL("last_template_alias", "<not_found>");
}
// Validation: No outputs produced; we avoid exposing const memory to the pool to prevent accidental mutation.

// Constructor stub for uuid_t *: allocate a 16-byte buffer and initialize it via supported APIs.
// Avoid calling uuid_generate_time_v6/v7 due to link errors in this environment.

uuid_t *uu = (uuid_t*)malloc(sizeof(uuid_t));
if (!uu) {
    // Allocation must succeed; otherwise we cannot provide a valid object to the pool.
    FUZZ_BAIL();
}

// Choose a construction path among safe, linked APIs.
unsigned int choice = *FUZZ_PARAM(unsigned int);
unsigned int method = choice % 10u; // 10 different paths (no v6/v7)

if (method == 0u) {
    // Initialize to nil UUID explicitly.
    uuid_clear(*uu);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "nil_clear");
} else if (method == 1u) {
    uuid_generate(*uu);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "default");
} else if (method == 2u) {
    uuid_generate_random(*uu);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "random_v4");
} else if (method == 3u) {
    uuid_generate_time(*uu);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "time_v1");
} else if (method == 4u) {
    int status = uuid_generate_time_safe(*uu);
    FUZZ_SET_ATTR_INT(uu, "time_safe_status", status);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "time_safe");
} else if (method == 5u) {
    // Name-based MD5 (v3): require namespace and optional name buffer.
    uuid_t ns_local; // stack uuid_t is a valid 16-byte buffer
    uuid_generate_random(ns_local);
    std::string name_buf = FUZZ_PARAM_STR();
    size_t maxlen = name_buf.size();
    size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % (maxlen + 1));
    const char *name_ptr = (len == 0) ? (const char*)nullptr : name_buf.data();
    if (len > 0 && name_ptr == nullptr) {
        // If len>0, name must be non-NULL and at least len bytes.
        FUZZ_BAIL();
    }
    uuid_generate_md5(*uu, ns_local, name_ptr, len);
    FUZZ_SET_ATTR_INT(uu, "name_len", (int)len);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "name_md5_v3");
} else if (method == 6u) {
    // Name-based SHA1 (v5).
    uuid_t ns_local; // any valid namespace UUID
    uuid_generate(ns_local);
    std::string name_buf = FUZZ_PARAM_STR();
    size_t maxlen = name_buf.size();
    size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % (maxlen + 1));
    const char *name_ptr = (len == 0) ? (const char*)nullptr : name_buf.data();
    if (len > 0 && name_ptr == nullptr) {
        FUZZ_BAIL();
    }
    uuid_generate_sha1(*uu, ns_local, name_ptr, len);
    FUZZ_SET_ATTR_INT(uu, "name_len", (int)len);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "name_sha1_v5");
} else if (method == 7u) {
    // Parse from NUL-terminated text.
    std::string text = FUZZ_PARAM_STR();
    int st = uuid_parse(text.c_str(), *uu);
    FUZZ_SET_ATTR_INT(uu, "parsed_ok", st);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "parsed_text");
} else if (method == 8u) {
    // Parse from a character range [start, end).
    std::string text = FUZZ_PARAM_STR();
    size_t n = text.size();
    size_t i = (size_t)(*FUZZ_PARAM(unsigned int) % (n + 1));
    size_t j = (size_t)(*FUZZ_PARAM(unsigned int) % (n + 1));
    if (i > j) { size_t tmp = i; i = j; j = tmp; }
    const char *in_start = text.data() + i;
    const char *in_end   = text.data() + j;
    int st = uuid_parse_range(in_start, in_end, *uu);
    FUZZ_SET_ATTR_INT(uu, "parsed_ok", st);
    FUZZ_SET_ATTR_INT(uu, "range_start", (int)i);
    FUZZ_SET_ATTR_INT(uu, "range_end", (int)j);
    FUZZ_SET_ATTR_STR(uu, "gen_kind", "parsed_range");
} else {
    // Retrieve a predefined template and copy it if available; otherwise fall back to generate.
    std::string alias_s = FUZZ_PARAM_STR();
    const uuid_t *tpl = uuid_get_template(alias_s.c_str());
    if (tpl) {
        // tpl points to read-only storage; copy into our writable buffer.
        uuid_copy(*uu, *tpl);
        FUZZ_SET_ATTR_STR(uu, "gen_kind", "template_copy");
    } else {
        // Unknown alias: ensure uu is still initialized with a valid UUID.
        uuid_generate(*uu);
        FUZZ_SET_ATTR_STR(uu, "gen_kind", "template_fallback_default");
    }
}

// Attach common derived attributes for downstream checks.
int v = uuid_variant(*uu);
int t = uuid_type(*uu);
int is_nil = uuid_is_null(*uu);
FUZZ_SET_ATTR_INT(uu, "variant", v);
FUZZ_SET_ATTR_INT(uu, "version", t);
FUZZ_SET_ATTR_INT(uu, "is_nil", is_nil);

// Output: hand the allocated, initialized uuid_t* back to the pool.

