import random
import struct
import time
import string

# UUID helpers
HEX_LOWER = '0123456789abcdef'
HEX_UPPER = '0123456789ABCDEF'

# Canonical UUID text length is 36; with NUL for C APIs, fuzz infra handles c_str() so no need to add NUL.
# We will emit byte strings that are valid UTF-8 text where appropriate.

NAMESPACE_TEMPLATES = {
    # Common, well-known namespace UUIDs (RFC 4122)
    'dns': '6ba7b810-9dad-11d1-80b4-00c04fd430c8',
    'url': '6ba7b811-9dad-11d1-80b4-00c04fd430c8',
    'oid': '6ba7b812-9dad-11d1-80b4-00c04fd430c8',
    'x500': '6ba7b814-9dad-11d1-80b4-00c04fd430c8',
}

WELL_KNOWN_TEMPLATES = {
    # Provide plausible aliases that uuid_get_template might accept in implementations
    'nil': '00000000-0000-0000-0000-000000000000',
    'max': 'ffffffff-ffff-ffff-ffff-ffffffffffff',
    'ns:DNS': NAMESPACE_TEMPLATES['dns'],
    'ns:URL': NAMESPACE_TEMPLATES['url'],
    'ns:OID': NAMESPACE_TEMPLATES['oid'],
    'ns:X500': NAMESPACE_TEMPLATES['x500'],
}

def rand_hex(rng, upper=False):
    return (HEX_UPPER if upper else HEX_LOWER)[rng.randrange(16)]

def make_uuid_text(rng, variant='canonical'):
    # Generate a canonical 8-4-4-4-12 UUID string.
    upper = rng.choice([False, True])
    def h(n):
        return ''.join(rand_hex(rng, upper) for _ in range(n))
    # Ensure version nibble reflects a reasonable set [1,3,4,5,6,7]
    version = rng.choice(['1', '3', '4', '5', '6', '7'])
    time_low = h(8)
    time_mid = h(4)
    time_hi = h(3) + version
    # Variant nibble: RFC 4122 variant must be 8..b (10xx)
    variant_nibble = rng.choice(list('89abAB'))
    clock_seq_hi = variant_nibble + h(1)
    clock_seq_low = h(2)
    node = h(12)
    s = f"{time_low}-{time_mid}-{time_hi}-{clock_seq_hi}{clock_seq_low}-{node}"
    if variant == 'upper':
        s = s.upper()
    elif variant == 'lower':
        s = s.lower()
    return s

def embed_uuid_in_text(rng, uuid_text):
    # Create a surrounding string and choose a random slice that may or may not isolate the UUID
    prefixes = [
        '', 'id=', 'uuid=', 'UserID:', 'object-', '(', '[', '{', 'prefix:', 'start ']
    suffixes = [
        '', ',end', ')', ']', '}', ' suffix', ' finish', ';', '\n', ' trailing']
    pre = rng.choice(prefixes)
    post = rng.choice(suffixes)
    filler_left = ''.join(rng.choice(string.ascii_letters + string.digits + '-_.,:/ ') for _ in range(rng.randrange(0, 8)))
    filler_right = ''.join(rng.choice(string.ascii_letters + string.digits + '-_.,:/ ') for _ in range(rng.randrange(0, 8)))
    text = filler_left + pre + uuid_text + post + filler_right
    # Choose a slice that sometimes exactly matches the UUID and sometimes includes extra chars
    start_base = rng.randrange(0, len(filler_left) + len(pre) + 1)
    # 50% pick exact UUID slice
    if rng.random() < 0.5:
        start = len(filler_left) + len(pre)
        end = start + len(uuid_text)
    else:
        start = start_base
        end = rng.randrange(start, len(text) + 1)
    return text, start, end

def make_name_bytes(rng):
    # Generate a name buffer with diverse content; occasionally empty
    modes = ['ascii', 'utf8', 'binary', 'path', 'url', 'dns']
    mode = rng.choice(modes)
    if mode == 'ascii':
        s = ''.join(rng.choice(string.ascii_letters + string.digits + ' _-.:@/') for _ in range(rng.randrange(1, 64)))
        return s.encode('ascii')
    if mode == 'utf8':
        samples = ['προτ', 'नाम', 'ユーザー', 'данные', '😀', 'café', 'ключ']
        base = rng.choice(samples)
        rep = rng.randrange(1, 8)
        return (base * rep).encode('utf-8')
    if mode == 'binary':
        n = rng.randrange(1, 64)
        return bytes(rng.randrange(0, 256) for _ in range(n))
    if mode == 'path':
        parts = [rng.choice(['usr','var','tmp','home','etc','opt','data']) for _ in range(rng.randrange(2,6))]
        return ('/' + '/'.join(parts)).encode('utf-8')
    if mode == 'url':
        host = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randrange(3,10))) + '.example.com'
        path = '/' + '/'.join(''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randrange(2,8))) for _ in range(rng.randrange(1,4)))
        return f"https://{host}{path}".encode('utf-8')
    if mode == 'dns':
        labels = [
            ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(rng.randrange(1, 10)))
            for _ in range(rng.randrange(2, 5))
        ]
        return ('.'.join(labels)).encode('ascii')
    return b''

def pick_strategy(rng):
    # Map strategies to fuzzer stubs usage: FUZZ_PARAM_STR is used for names and parse text.
    return rng.choice([
        'parse_text_lower',
        'parse_text_upper',
        'parse_text_mixed',
        'parse_range_exact',
        'parse_range_extra',
        'name_md5_nonempty',
        'name_md5_empty',
        'name_sha1_nonempty',
        'name_sha1_empty',
        'template_alias',
        'template_alias_unknown'
    ])

def build_for_strategy(rng, strategy):
    # The fuzzer may request multiple FUZZ_PARAM_STR from the same buffer pool; we provide a single buffer.
    # We craft the buffer such that when used as a std::string it contains appropriate content.
    if strategy.startswith('parse_text'):
        variant = 'lower' if 'lower' in strategy else ('upper' if 'upper' in strategy else 'canonical')
        uuid_text = make_uuid_text(rng, variant=variant)
        return uuid_text.encode('ascii')
    if strategy.startswith('parse_range'):
        uuid_text = make_uuid_text(rng)
        text, start, end = embed_uuid_in_text(rng, uuid_text)
        # Provide the whole text; the fuzzer stub independently chooses i,j. Our content includes a valid UUID.
        return text.encode('utf-8')
    if strategy == 'name_md5_nonempty' or strategy == 'name_sha1_nonempty':
        return make_name_bytes(rng)
    if strategy == 'name_md5_empty' or strategy == 'name_sha1_empty':
        return b''
    if strategy == 'template_alias':
        alias = rng.choice(list(WELL_KNOWN_TEMPLATES.keys()) + list(NAMESPACE_TEMPLATES.keys()))
        return alias.encode('ascii')
    if strategy == 'template_alias_unknown':
        # Likely unknown alias leading to fallback path
        unknown = 'alias_' + ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randrange(4,10)))
        return unknown.encode('ascii')
    # Fallback: emit a valid UUID
    return make_uuid_text(rng).encode('ascii')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    strategy = pick_strategy(rng)
    data = build_for_strategy(rng, strategy)
    # Ensure size constraints
    if len(data) > 4096:
        data = data[:4096]
    return bytes(data)
